const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry - Keukenhof Garden point with 500m buffer
  const keukenhof = ee.Geometry.Point([4.5464, 52.2667]).buffer(500);

  // 2. Date ranges - exact dates specified in question
  const date1 = '2018-04-21';
  const date2 = '2018-05-07';

  // 3. Data acquisition - Sentinel-2 MSI (high resolution for flowers)
  function getImage(date) {
    const collection = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
      .filterBounds(keukenhof)
      .filterDate(date, ee.Date(date).advance(1, 'day')) // Exact date
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

    // Cloud masking
    function maskClouds(image) {
      const cloudProb = image.select('MSK_CLDPRB');
      const cloudMask = cloudProb.lt(20);
      return image.updateMask(cloudMask);
    }

    const processed = collection.map(maskClouds).median();
    return {collection: collection, image: processed};
  }

  const img1 = getImage(date1);
  const img2 = getImage(date2);

  // 4. Check collection sizes
  const count1 = img1.collection.size().getInfo();
  const count2 = img2.collection.size().getInfo();

  console.log(`April 21 Images: ${count1}`);
  console.log(`May 7 Images: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 5. For red flower detection, use Red band (B4) and potentially NDVI
  // Red band (B4) for red flower visibility
  const redBand = 'B4';

  // Check valid pixels in red band
  function countPixels(imgObj) {
    const count = imgObj.image.select(redBand)
      .reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: keukenhof,
        scale: 10,
        maxPixels: 1e9
      }).get(redBand);
    return ee.Number(count).getInfo();
  }

  const pixels1 = countPixels(img1);
  const pixels2 = countPixels(img2);

  console.log(`April valid pixels: ${pixels1}`);
  console.log(`May valid pixels: ${pixels2}`);

  if (pixels1 === 0 || pixels2 === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 6. Calculate mean red reflectance for comparison
  function meanRed(imgObj) {
    const mean = imgObj.image.select(redBand)
      .reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: keukenhof,
        scale: 10,
        maxPixels: 1e9
      }).get(redBand);
    return ee.Number(mean).getInfo();
  }

  const mean1 = meanRed(img1);
  const mean2 = meanRed(img2);

  console.log(`April mean red: ${mean1?.toFixed(4) || 'null'}`);
  console.log(`May mean red: ${mean2?.toFixed(4) || 'null'}`);

  // 7. Validation and comparison
  if (mean1 === null || mean2 === null || 
      isNaN(mean1) || isNaN(mean2) ||
      mean1 > 1 || mean2 > 1 || // Reflectance should be 0-1
      mean1 < 0 || mean2 < 0) {
    console.log('<answer>C3</answer>');
  } else if (mean1 > mean2) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
